  function load(){try{var raw=localStorage.getItem(KEY);if(raw){var p=JSON.parse(raw);if(p&&p.version===2){state=Object.assign(fresh(),p);state.grid=(p.grid||[]).slice(0,TOTAL);while(state.grid.length<TOTAL)state.grid.push(null);if(!state.grid.some(function(x){return x&&x.kind==='generator';})){if(!state.grid[23])state.grid[23]={kind:'generator',family:'herb',name:'百草药篓'};if(!state.grid[26])state.grid[26]={kind:'generator',family:'tool',name:'医师药箱'};}state.beast=Object.assign(fresh().beast,p.beast||{});return;}}}catch(e){} state=fresh();}
