  function empty(){for(var i=0;i<TOTAL;i++)if(unlocked(i)&&!state.grid[i])return i;return -1;}
  function tick(){var now=Date.now(),d=now-(state.lastEnergyTick||now);if(d>=ENERGY_MS&&state.energy<state.maxEnergy){var n=Math.min(Math.floor(d/ENERGY_MS),state.maxEnergy-state.energy);state.energy+=n;state.lastEnergyTick+=n*ENERGY_MS;save();}else if(state.energy>=state.maxEnergy)state.lastEnergyTick=now;}
  function toast(s){clearTimeout(toastTimer);var r=q('toast-root');r.innerHTML='<div class="toast">'+s+'</div>';toastTimer=setTimeout(function(){r.innerHTML='';},2600);}
